#!/usr/bin/env python3
from __future__ import annotations

import json
from pathlib import Path


TASK_ID = "CSX-049_Q2"
EVENT_ID = "CSX-049"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = Path(__file__).resolve().parents[3]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

REPORT = "data/event_reports/event_reports_002_Wikipedia_Northeast_Ida_effects.json"
ERA5 = "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json"
GPM = "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json"
CHIRPS = "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json"
WORLDPOP = "data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json"
OSM_SMALL = "data/exposure_impact/exposure_impact_002_Overpass_small_roads_and_critical_amenities.json"
S1 = "data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json"
ALPHA = "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json"


def load_json(rel_path: str) -> dict:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def round2(value: float) -> float:
    return round(float(value), 2)


def report_flag_count(text: str) -> int:
    lower = text.lower()
    flags = [
        "shutting down numerous roads",
        "halting public transit",
        "cancelling hundreds of flights",
        "hundreds of cars",
        "high-water rescues",
        "flash flood emergencies",
    ]
    return sum(flag in lower for flag in flags)


def osm_counts() -> dict[str, int]:
    elements = load_json(OSM_SMALL).get("elements", [])
    return {
        "highway_elements": sum("highway" in item.get("tags", {}) for item in elements),
        "amenity_elements": sum("amenity" in item.get("tags", {}) for item in elements),
    }


def build_rubric() -> dict:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Final JSON and label",
                "points": 3,
                "description": "Returns the requested compact JSON and the rainfall-disruption-exposure response label.",
                "partial_credit": "Partial credit for a recoverable JSON answer with a compatible but incomplete label.",
            },
            {
                "name": "Rainfall support",
                "points": 4,
                "description": "Computes the three-product rainfall support count and minimum peak-to-mean ratio correctly.",
                "partial_credit": "Partial credit for correct method with one product error.",
            },
            {
                "name": "Report flags",
                "points": 3,
                "description": "Counts the six report disruption flags correctly.",
                "partial_credit": "Partial credit for at least four correct flags.",
            },
            {
                "name": "Exposure and infrastructure",
                "points": 3,
                "description": "Reports the population total and OSM highway/amenity counts correctly, treating masked exposure and infrastructure statistics as package-authoritative and not judging them by internal coordinates or place names.",
                "partial_credit": "Partial credit for one correct exposure component.",
            },
            {
                "name": "Image-response values",
                "points": 3,
                "description": "Computes the Sentinel-1 VV range and embedding max-to-mean ratio correctly.",
                "partial_credit": "Partial credit for one correct image-response metric.",
            },
            {
                "name": "Score ledger",
                "points": 3,
                "description": "Applies all five score tests and reports score_0_to_5 = 5.",
                "partial_credit": "Partial credit for one test error with the same broad conclusion.",
            },
            {
                "name": "Computed interpretation",
                "points": 1,
                "description": "Keeps the interpretation tied to the computed ledger.",
                "partial_credit": "Partial credit for a longer but still numeric interpretation.",
            },
        ],
    }


def build_output() -> dict:
    report = load_json(REPORT)
    era5 = load_json(ERA5)["stats"]
    gpm = load_json(GPM)["stats"]
    chirps = load_json(CHIRPS)["stats"]
    population = round(load_json(WORLDPOP)["population_sum"]["population"])
    infrastructure = osm_counts()
    s1 = load_json(S1)["stats"]
    alpha = load_json(ALPHA)["stats"]

    precip_maxima = {
        "era5": era5["precipitation_sum_mm_max"],
        "gpm": gpm["gpm_event_precip_mm_max"],
        "chirps": chirps["chirps_event_precip_mm_max"],
    }
    ratios = {
        "era5": era5["precipitation_sum_mm_max"] / era5["precipitation_sum_mm_mean"],
        "gpm": gpm["gpm_event_precip_mm_max"] / gpm["gpm_event_precip_mm_mean"],
        "chirps": chirps["chirps_event_precip_mm_max"] / chirps["chirps_event_precip_mm_mean"],
    }
    precip_support = sum(
        [
            precip_maxima["era5"] >= 10,
            precip_maxima["gpm"] >= 18,
            precip_maxima["chirps"] >= 18,
        ]
    )
    s1_range = s1["s1_vv_post_minus_pre_db_max"] - s1["s1_vv_post_minus_pre_db_min"]
    embedding_ratio = alpha["alphaearth_1_minus_cosine_max"] / alpha["alphaearth_1_minus_cosine_mean"]
    flags = report_flag_count(report["extract"])
    tests = {
        "rainfall_support_count_eq3": precip_support == 3,
        "report_flags_ge5": flags >= 5,
        "population_ge50000": population >= 50000,
        "infrastructure_present": infrastructure["highway_elements"] >= 10 and infrastructure["amenity_elements"] >= 1,
        "image_response_pass": s1_range >= 25 and embedding_ratio >= 20,
    }

    primary_gt = {
        "answer_label": "rainfall_disruption_exposure_response_consistent",
        "precip_peak_support_count": precip_support,
        "min_peak_to_mean_ratio": round2(min(ratios.values())),
        "report_flag_count": flags,
        "population_sum": population,
        "infrastructure_counts": infrastructure,
        "image_response": {
            "s1_vv_range_db": round2(s1_range),
            "embedding_max_to_mean": round2(embedding_ratio),
        },
        "score_0_to_5": sum(tests.values()),
        "computed_interpretation": (
            "The record has three-product rainfall peak support, six disruption flags, nonzero exposure and "
            "infrastructure anchors, and two image-response checks above threshold."
        ),
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "exposure_impact_score_ledger",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "masked_spatial_product_contract": {
                "applies_to": [WORLDPOP, OSM_SMALL],
                "derived_statistics_authoritative": True,
                "absolute_coordinates_place_names_and_georeferencing_not_for_event_validity": True,
            },
            "precip_maxima_mm": {key: round2(value) for key, value in precip_maxima.items()},
            "peak_to_mean_ratios": {key: round2(value) for key, value in ratios.items()},
            "decision_tests": tests,
            "score_thresholds": {
                "era5_peak_mm": 10,
                "satellite_peak_mm": 18,
                "report_flags": 5,
                "population": 50000,
                "highway_elements": 10,
                "amenity_elements": 1,
                "s1_range_db": 25,
                "embedding_max_to_mean": 20,
            },
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [REPORT, ERA5, GPM, CHIRPS, WORLDPOP, OSM_SMALL, S1, ALPHA],
            "notes": "WorldPop and OSM exposure files are treated as spatially masked products; derived statistics are authoritative, while absolute coordinates/place names/georeferencing are not event-location validity checks.",
        },
    }


def main() -> None:
    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(build_output(), indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
